"""Parse ASSERT/COVER result lines emitted by a testbench.

Recognised single-line forms (leading/trailing whitespace is ignored, and
unrecognised lines are ordinary simulator output):

    ASSERT PASS <name>
    ASSERT FAIL <name> [<message>]
    COVER <name>

A result whose name is empty after stripping whitespace is ignored.
"""

from collections import OrderedDict


class AssertionRecord:
    __slots__ = ("name", "status", "fail_count")

    def __init__(self, name):
        self.name = name
        self.status = "pass"
        self.fail_count = 0

    def to_dict(self):
        return {
            "name": self.name,
            "status": self.status,
            "fail_count": self.fail_count,
        }


class CoverageRecord:
    __slots__ = ("name", "hits")

    def __init__(self, name):
        self.name = name
        self.hits = 0

    def to_dict(self):
        return {"name": self.name, "hits": self.hits}


class ResultCollector:
    """Collects assertion/coverage results in first-seen order.

    An assertion's status is the status of its *last* matching result line;
    ``fail_count`` accumulates every FAIL line seen for that name.
    """

    def __init__(self):
        self._assertions = OrderedDict()
        self._coverage = OrderedDict()

    def feed_line(self, line):
        # Drop only the trailing newline; fields are stripped individually.
        if line.endswith("\n"):
            line = line[:-1]
        stripped = line.strip()
        if not stripped:
            return

        parts = stripped.split(None, 2)
        if parts[0] != "ASSERT" and parts[0] != "COVER":
            return

        if parts[0] == "COVER":
            rest = stripped[len("COVER"):].strip()
            tokens = stripped.split(None, 1)
            name = tokens[1].strip() if len(tokens) > 1 else ""
            if name:
                record = self._coverage.get(name)
                if record is None:
                    record = CoverageRecord(name)
                    self._coverage[name] = record
                record.hits += 1
            return

        # ASSERT requires PASS/FAIL and a name.
        if len(parts) < 3:
            return
        verdict = parts[1]
        if verdict not in ("PASS", "FAIL"):
            return
        if verdict == "FAIL":
            tokens = stripped.split(None, 3)
        else:
            tokens = stripped.split(None, 2)
        if len(tokens) < 3:
            return
        if verdict == "FAIL":
            name = tokens[2].strip()
            # Everything after the name, if present, is the free-form message.
            message = tokens[3].strip() if len(tokens) > 3 else ""
        else:
            name_and_rest = tokens[2]
            sp = name_and_rest.find(None) if False else -1
            name = name_and_rest.strip()
            message = ""
        if not name:
            return

        record = self._assertions.get(name)
        if record is None:
            record = AssertionRecord(name)
            self._assertions[name] = record
        record.status = "fail" if verdict == "FAIL" else "pass"
        if verdict == "FAIL":
            record.fail_count += 1
        # message retained nowhere yet; reserved for future schema extension.
        _ = message

    def feed_text(self, text):
        for line in text.splitlines():
            self.feed_line(line)

    @property
    def assertions(self):
        return [rec.to_dict() for rec in self._assertions.values()]

    @property
    def coverage(self):
        return [rec.to_dict() for rec in self._coverage.values()]

    @property
    def failed_assertions(self):
        return [name for name, rec in self._assertions.items() if rec.status == "fail"]

