def _display_path(path, workdir_abs):
    """Path representation safe to put in the report."""
    if not os.path.isabs(path):
        return path
    try:
        rel = os.path.relpath(path, workdir_abs)
    except ValueError:
        rel = None
    if rel is not None and not rel.startswith(".." + os.sep) and rel != "..":
        return rel
    # Absolute path outside the working directory: keep only the file name.
    return os.path.basename(path)


def _scrub_text(text, workdir_abs):
    """Remove absolute paths from captured tool output.

    Paths inside the working directory are shown relative to it; paths
    outside are reduced to their basename. Message text is otherwise kept
    byte-for-byte.
    """
    if not text:
        return text
    prefix = workdir_abs.rstrip(os.sep)

    def replace(match):
        found = match.group(0)
        if found == "/":
            return found
        if found.startswith(prefix + os.sep) or found == prefix:
