module counter #(
  parameter WIDTH = 4
) (
  input  wire             clk,
  input  wire             rst,
  output reg [WIDTH-1:0]  q
);
  always @(posedge clk or posedge rst) begin
    if (rst)
      q <= {WIDTH{1'b0}};
    else
      q <= q + {{(WIDTH-1){1'b0}}, 1'b1};
  end
endmodule

// A second design unit used to verify multi-source compile ordering.
module extra (
  input  wire a,
  input  wire b,
  output wire y
);
  assign y = a & b;
endmodule

`timescale 1ns/1ps

module tb;
  reg clk = 1'b0;
  reg rst = 1'b1;
  wire [3:0] q;

  integer seed = 0;

  counter dut (
    .clk(clk),
    .rst(rst),
    .q(q)
  );

  always #5 clk = ~clk;

  initial begin
    if ($value$plusargs("seed=%d", seed)) ;
    $display("starting tb seed=%0d", seed);

    // Reset value.
    #1;
    if (q === 4'd0)
      $display("ASSERT PASS check_reset");
    else
      $display("ASSERT FAIL check_reset q=%0d", q);
    $display("COVER reset_seen");

    #12 rst = 1'b0;
    repeat (3) @(posedge clk);
    #1;
    if (q === 4'd3)
      $display("ASSERT PASS check_count");
    else
      $display("ASSERT FAIL check_count q=%0d", q);
    $display("COVER counting_seen");
    $display("COVER counting_seen");
    $display("COVER counting_seen");

    #10 $finish;
  end
endmodule

`timescale 1ns/1ps

module tb;
  initial begin
    // Flaky assertion: fails first, passes last -> final status pass,
    // but the earlier failure is counted.
    $display("ASSERT FAIL flaky first sample wrong");
    #2;
    $display("ASSERT PASS flaky");

    // Stable assertion: final result is FAIL.
    $display("ASSERT FAIL stable mismatch one");
    #2;
    $display("ASSERT FAIL stable mismatch two");

    #5 $finish;
  end
endmodule

`timescale 1ns/1ps

module tb;
  initial begin
    #1 $display("ASSERT PASS only_check");
    // Deliberately emits no COVER lines: absence of coverage is allowed.
    #5 $finish;
  end
endmodule

`timescale 1ns/1ps

module tb_fatal;
  initial begin
    #1 $display("ASSERT PASS before_crash");
    #2 $fatal(1, "simulation blew up");
  end
endmodule

